/* ── Anchor: trigger plus its clear button, which are siblings ─────────────
   A button can't hold a button, so the ✕ sits over the trigger's right end
   and the trigger reserves room for it. */

.root {
  position: relative;
  display: inline-flex;
  align-items: center;
  max-width: 100%;
}

.rootField {
  display: flex;
  width: 100%;
}

/* ── Trigger, chip appearance: the reference recessed filter chip (§4.4) ─── */

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: var(--chip-height, var(--control-h-sm));
  max-width: 100%;
  padding: 0 calc(10px * var(--density)) 0 calc(11px * var(--density));
  border: 0;
  border-radius: var(--chip-radius, var(--r-sm));
  background: var(--recess-fill);
  box-shadow: var(--shadow-recess);
  font-family: var(--font-body);
  font-size: var(--text-caption);
  font-weight: 700;
  color: var(--ink-muted);
  white-space: nowrap;
  transition:
    background-color var(--dur) var(--ease),
    color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.chip:hover:not(:disabled) {
  background: var(--recess-fill-hover);
  color: var(--ink-body);
}

.chip:active:not(:disabled) {
  box-shadow: inset 0 1px 2px rgba(var(--rgb-contact), 0.14), inset 0 -1px 0 rgba(var(--rgb-white), 0.6);
}

.chip:focus-visible {
  outline: none;
  box-shadow: var(--shadow-recess), var(--focus-ring);
}

.chip.clearable {
  padding-right: 30px;
}

/* ── Trigger, field appearance: Select's grey frosted field ─────────────
   Same fill, blur and recess as .field[class] in Select, at the TextInput
   md height and radius, so the two sit level in a form row. */

.field {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-height: 44px;
  padding: 0 12px 0 14px;
  border: 1.5px solid transparent;
  border-radius: var(--r-md);
  background: var(--recess-fill);
  -webkit-backdrop-filter: blur(12px) saturate(140%);
  backdrop-filter: blur(12px) saturate(140%);
  box-shadow: var(--shadow-recess);
  font-family: var(--font-body);
  font-size: var(--text-input);
  color: var(--ink-body);
  text-align: left;
  transition:
    background-color var(--dur) var(--ease),
    border-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease),
    color var(--dur) var(--ease);
}

.field:hover:not(:disabled) {
  background: var(--recess-fill-hover);
}

.field:active:not(:disabled) {
  box-shadow: inset 0 1px 2px rgba(var(--rgb-contact), 0.14), inset 0 -1px 0 rgba(var(--rgb-white), 0.6);
}

.field:focus-visible {
  outline: none;
  border-color: var(--field-focus-border, rgba(var(--rgb-brand), 0.7));
  box-shadow: var(--shadow-recess), var(--field-focus-ring, var(--focus-halo));
}

.field.clearable {
  padding-right: 44px;
}

/* ── Shared states ─────────────────────────────────────────────────────── */

/* A range is set. Tint and ink only: a ring would make this one control
   look outlined beside its neighbours. */
.active,
.active:hover:not(:disabled) {
  background: var(--chip-active-fill);
  color: var(--brand-deep);
  font-weight: 700;
  box-shadow: var(--chip-active-shadow);
}

.chip.active:hover:not(:disabled),
.field.active:hover:not(:disabled) {
  background: var(--chip-active-fill-hover);
}

.open,
.open:hover:not(:disabled) {
  background: var(--wash-active);
  color: var(--ink-brand);
}

.field.open {
  border-color: var(--field-focus-border, rgba(var(--rgb-brand), 0.7));
  box-shadow: var(--shadow-recess), var(--field-focus-ring, var(--focus-halo));
}

.chip:disabled,
.field:disabled {
  cursor: not-allowed;
  background: var(--recess-fill);
  color: var(--ink-disabled);
}

.field:disabled {
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  box-shadow: none;
  background: rgba(var(--rgb-brand-deep), 0.05);
}

/* Invalid keeps the recess and adds the danger red edge, as Select does. The
   chip has no border, so its edge is drawn as an inset ring. */
.field[aria-invalid="true"] {
  border-color: rgba(var(--rgb-danger), 0.75);
  background: rgba(var(--rgb-danger), 0.06);
}

.field[aria-invalid="true"]:focus-visible,
.field[aria-invalid="true"].open {
  border-color: var(--danger-base);
  box-shadow: var(--shadow-recess), var(--field-focus-ring-invalid, 0 0 0 4px rgba(var(--rgb-danger), 0.14));
}

.chip[aria-invalid="true"] {
  background: rgba(var(--rgb-danger), 0.06);
  box-shadow: var(--shadow-recess), inset 0 0 0 1.5px rgba(var(--rgb-danger), 0.75);
}

.chip[aria-invalid="true"]:focus-visible {
  box-shadow:
    var(--shadow-recess),
    inset 0 0 0 1.5px rgba(var(--rgb-danger), 0.75),
    0 0 0 2px var(--focus-gap),
    0 0 0 4px var(--danger-base);
}

.icon {
  flex-shrink: 0;
  opacity: 0.8;
}

.field .icon {
  color: var(--ink-muted);
  opacity: 1;
}

.field.active .icon,
.field.open .icon {
  color: var(--ink-brand);
}

.field:disabled .icon {
  color: var(--ink-disabled);
}

.value {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* On the recess the lighter placeholder ink falls to ~3.5:1; muted holds. */
.field .placeholder {
  color: var(--ink-muted);
}

.field:disabled .placeholder {
  color: var(--ink-disabled);
}

.chevron {
  flex-shrink: 0;
  opacity: 0.7;
  transition: transform var(--dur) ease;
}

.field .chevron {
  color: var(--ink-muted);
  opacity: 1;
}

.open .chevron {
  transform: rotate(180deg);
}

/* Clear: inset from the trigger edge, so its radius steps down to 4. */
.clear {
  position: absolute;
  right: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: var(--r-2xs);
  background: transparent;
  color: var(--ink-brand);
  opacity: 0.75;
  transition:
    opacity var(--dur) var(--ease),
    background-color var(--dur) var(--ease);
}

.rootField .clear {
  right: 8px;
  width: 28px;
  height: 28px;
}

.clear:hover {
  opacity: 1;
  background: rgba(var(--rgb-white), 0.7);
}

.clear:active {
  background: rgba(var(--rgb-white), 0.9);
}

.clear:focus-visible {
  outline: none;
  opacity: 1;
  box-shadow: 0 0 0 2px var(--focus-color);
}

/* ── Popover: solid white float, never glass ────────────────────────────── */

.popup {
  position: fixed;
  z-index: var(--z-popover);
  max-width: calc(100vw - 16px);
  max-height: calc(100vh - 16px);
  overflow: auto;
  overscroll-behavior: contain;
  background: var(--surface-solid);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-menu);
  animation: pop-in var(--dur) var(--ease-out);
}

.body {
  display: flex;
}

/* Presets: a recessed side panel, tinted apart from the white calendar side
   so the shortcuts read as their own column. A faint
   accent wash over the white float, a hairline divider, and a soft inner
   shade along the divider so the calendar side sits a step above it. The
   picked preset lifts out of the recess as a white key. The flat preset gets the
   same structure through the tokens: a flat neutral grey, square. */
.presets {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 156px;
  margin: 0;
  padding: 12px 8px;
  list-style: none;
  background: linear-gradient(var(--wash-subtle), var(--wash-subtle)), var(--surface-solid);
  border-right: 1px solid var(--line);
  box-shadow: inset -6px 0 10px -8px rgba(var(--rgb-contact), 0.12);
}

/* Items: 6px inside a 12px popover corner, so radius 6. */
.preset {
  display: block;
  width: 100%;
  padding: 8px 10px;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  font-family: var(--font-body);
  font-size: 13.5px;
  color: var(--ink-body);
  text-align: left;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color var(--dur-fast) var(--ease),
    box-shadow var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease);
}

.preset:hover:not(:disabled) {
  background: var(--wash-active);
  color: var(--ink-brand);
}

.preset:active:not(:disabled) {
  background: var(--wash-strong);
}

.preset:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.presetActive,
.presetActive:hover:not(:disabled) {
  background: var(--surface-solid);
  box-shadow:
    inset 0 0 0 1px var(--line-brand),
    0 1px 3px rgba(var(--rgb-contact), 0.1);
  color: var(--ink-brand);
  font-weight: 700;
}

.presetActive:focus-visible {
  box-shadow: var(--focus-ring);
}

.preset:disabled {
  cursor: not-allowed;
  color: var(--ink-disabled);
}

.calendars {
  padding: 14px 16px 10px;
}

.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 12px 10px 16px;
  border-top: 1px solid var(--line-soft);
  background: linear-gradient(var(--wash-row), var(--wash-row)), var(--surface-solid);
}

.summary {
  min-width: 0;
  font-size: var(--text-small);
  color: var(--ink-muted);
  font-variant-numeric: tabular-nums;
}

.summarySet {
  font-weight: 700;
  color: var(--ink-body);
}

.actions {
  display: flex;
  flex-shrink: 0;
  gap: 8px;
}

/* One calendar: presets become a wrapping row above it, so the popover
   fits a phone. */
.popupNarrow .body {
  flex-direction: column;
}

.popupNarrow .presets {
  flex-direction: row;
  flex-wrap: wrap;
  min-width: 0;
  max-width: 328px;
  padding: 8px;
  border-right: 0;
  border-bottom: 1px solid var(--line);
  box-shadow: inset 0 -6px 10px -8px rgba(var(--rgb-contact), 0.12);
}

.popupNarrow .presets li {
  flex: 0 0 auto;
}

.popupNarrow .preset {
  padding: 6px 9px;
  font-size: var(--text-small);
}

.popupNarrow .footer {
  flex-direction: column;
  align-items: stretch;
}

.popupNarrow .actions {
  justify-content: flex-end;
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
}

/* Inline: the panel shown open under the trigger, in flow, for docs and
   thumbnails. */
.inlineWrap {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
}

.popupInline[class] {
  position: static;
  max-height: none;
  animation: none;
}

"use client";

import { Fragment, useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent } from "react";
import { cx } from "../_internal/cx";
import { Portal } from "../_internal/portal";
import { focusableWithin, placePopup } from "../_internal/position";
import { Button } from "../Button/Button";
import { Calendar, type DateRange } from "../DateField/Calendar";
import { addMonths, formatDate, todayIso, type IsoDate } from "../DateField/date-utils";
import { mergeDescribedBy, useField } from "../Field/Field";
import { IconCalendar, IconChevronDown, IconX } from "../Icon/Icon";
import {
  clampRange,
  daysInRange,
  DEFAULT_DATE_RANGE_PRESETS,
  EMPTY_RANGE,
  formatDateRange,
  normaliseRange,
  sameRange,
  type DateRangePreset,
} from "./range-utils";
import styles from "./DateRangeFilter.module.css";

export type DateRangeFilterProps = {
  /** Both null = no filter. A half-picked range never reaches onChange. */
  value: DateRange;
  onChange: (value: DateRange) => void;
  presets?: ReadonlyArray<DateRangePreset>;
  min?: IsoDate;
  max?: IsoDate;
  isDateDisabled?: (date: IsoDate) => boolean;
  /** Shown when no range is set. */
  placeholder?: string;
  /** chip = 32px filter-bar chip. field = form-control height, beside Select. */
  appearance?: "chip" | "field";
  /** Calendars side by side. Defaults to 2, or 1 under 640px. */
  months?: 1 | 2;
  disabled?: boolean;
  invalid?: boolean;
  id?: string;
  /** Names the control. The current range is appended, so it is read too. */
  "aria-label"?: string;
  className?: string;
  /**
   * Show the panel open, in place under the trigger: no portal, no focus
   * move, no outside-click listener. For docs and thumbnails.
   */
  inline?: boolean;
};

/**
 * Date range filter: the reference recessed chip trigger over a presets list
 * and one or two calendars. Picking is a draft: nothing reaches onChange
 * until Apply, and Esc or clicking away puts the old range back. The ✕ on
 * the trigger is its own button and clears at once, without opening.
 *
 * The popover is a small dialog: focus goes into the calendar on open, Tab
 * is held inside it, and focus comes back to the trigger on Apply or Esc.
 */
export function DateRangeFilter({
  value,
  onChange,
  presets = DEFAULT_DATE_RANGE_PRESETS,
  min,
  max,
  isDateDisabled,
  placeholder = "All dates",
  appearance = "chip",
  months: monthsProp,
  disabled,
  invalid: invalidProp,
  id: idProp,
  "aria-label": ariaLabel,
  className,
  inline = false,
}: DateRangeFilterProps) {
  const field = useField();
  const autoId = useId();
  const id = idProp ?? field?.id ?? `daterange-${autoId}`;
  const dialogId = `${id}-dialog`;
  const valueId = `${id}-value`;
  const summaryId = `${id}-summary`;
  const invalid = invalidProp ?? field?.invalid ?? false;

  const [openState, setOpen] = useState(false);
  const open = inline || openState;
  const [draft, setDraft] = useState<DateRange>(() => (inline ? normaliseRange(value) : EMPTY_RANGE));
  const [today, setToday] = useState<IsoDate | null>(null);
  const [months, setMonths] = useState<1 | 2>(2);
  // Bumped when a preset moves the calendar, which remounts it on the new
  // range. Zero only for the mount that opens the popover, which takes focus.
  const [calendarKey, setCalendarKey] = useState(0);

  const anchorRef = useRef<HTMLSpanElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const popupRef = useRef<HTMLDivElement>(null);

  const applied = normaliseRange(value);
  const hasValue = applied.start !== null;
  const label = formatDateRange(applied) ?? placeholder;

  const openPopover = () => {
    if (disabled) return;
    setDraft(applied);
    setToday(todayIso());
    setMonths(monthsProp ?? (window.matchMedia("(max-width: 639px)").matches ? 1 : 2));
    setCalendarKey(0);
    setOpen(true);
  };

  /** Esc and click-away discard the draft; focus only returns for Esc. */
  const cancel = (returnFocus: boolean) => {
    setOpen(false);
    if (returnFocus) triggerRef.current?.focus();
  };

  const apply = () => {
    const next = normaliseRange(draft);
    if (!sameRange(next, applied)) onChange(next);
    setOpen(false);
    triggerRef.current?.focus();
  };

  const clearValue = () => {
    onChange(EMPTY_RANGE);
    setOpen(false);
    triggerRef.current?.focus();
  };

  // Inline: today is read after mount, as an opening would, so the server
  // and client renders agree.
  useEffect(() => {
    if (!inline) return;
    const frame = requestAnimationFrame(() => setToday(todayIso()));
    return () => cancelAnimationFrame(frame);
  }, [inline]);

  // Position against the trigger, and keep it there through scroll and resize.
  useLayoutEffect(() => {
    if (!open || inline) return;
    const anchor = anchorRef.current;
    const popup = popupRef.current;
    if (!anchor || !popup) return;
    const place = () => placePopup(anchor, popup, { align: "start" });
    place();
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    return () => {
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
    };
  }, [open, inline, months]);

  // Click away cancels. The trigger toggles itself, so it is excluded.
  useEffect(() => {
    if (!open || inline) return;
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as Node;
      if (anchorRef.current?.contains(target) || popupRef.current?.contains(target)) return;
      setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open, inline]);

  const onPopupKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Escape") {
      // Stop here so an enclosing Modal stays open.
      e.preventDefault();
      e.stopPropagation();
      cancel(true);
      return;
    }
    if (e.key !== "Tab" || !popupRef.current) return;
    // Roving-tabindex days sit at -1; only real tab stops bound the trap.
    const items = focusableWithin(popupRef.current).filter((el) => el.tabIndex >= 0);
    if (items.length === 0) return;
    const first = items[0];
    const last = items[items.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  };

  const resolved = today
    ? presets.map((p) => ({ preset: p, range: clampRange(p.range(today), min, max) }))
    : [];
  const draftWhole = draft.start && draft.end ? draft : null;
  const matchedId = draftWhole ? resolved.find((r) => r.range && sameRange(r.range, draftWhole))?.preset.id : undefined;

  const choosePreset = (range: DateRange) => {
    setDraft(range);
    setCalendarKey((k) => k + 1);
  };

  // First pane: with nothing picked, two panes show last month and this one,
  // since a filter looks back from today.
  const defaultMonth = today && months === 2 ? addMonths(today, -1) : (today ?? undefined);

  const summary = (() => {
    if (draft.start && draft.end) {
      const days = daysInRange(draft.start, draft.end);
      return draft.start === draft.end
        ? `${formatDate(draft.start)} only`
        : `${formatDate(draft.start)} to ${formatDate(draft.end)} · ${days} days`;
    }
    if (draft.start) return `From ${formatDate(draft.start)}. Pick an end date, or apply for that day only.`;
    return `No range picked. Showing ${placeholder.toLowerCase()}.`;
  })();

  const isChip = appearance === "chip";
  const labelledBy = !ariaLabel && field?.labelId ? `${field.labelId} ${valueId}` : undefined;

  const popup = (
      <div
        ref={popupRef}
        id={dialogId}
        role="dialog"
        aria-label={ariaLabel ? `Choose ${ariaLabel.toLowerCase()}` : "Choose date range"}
        aria-describedby={summaryId}
        data-surface="solid"
        className={cx(styles.popup, months === 1 && styles.popupNarrow, inline && styles.popupInline)}
        onKeyDown={onPopupKeyDown}
      >
        <div className={styles.body}>
          <ul className={styles.presets} aria-label="Presets">
            {resolved.map(({ preset, range }) => (
              <li key={preset.id}>
                <button
                  type="button"
                  className={cx(styles.preset, preset.id === matchedId && styles.presetActive)}
                  aria-pressed={preset.id === matchedId}
                  disabled={!range}
                  onClick={() => range && choosePreset(range)}
                >
                  {preset.label}
                </button>
              </li>
            ))}
          </ul>

          <div className={styles.calendars}>
            <Calendar
              key={calendarKey}
              range={draft}
              onRangeChange={setDraft}
              min={min}
              max={max}
              isDateDisabled={isDateDisabled}
              defaultMonth={defaultMonth}
              numberOfMonths={months}
              autoFocus={!inline && calendarKey === 0}
            />
          </div>
        </div>

        <div className={styles.footer}>
          <p id={summaryId} className={cx(styles.summary, draft.start && styles.summarySet)} aria-live="polite">
            {summary}
          </p>
          <div className={styles.actions}>
            <Button
              variant="ghost"
              size="sm"
              disabled={!draft.start}
              onClick={() => {
                setDraft(EMPTY_RANGE);
                popupRef.current?.querySelector<HTMLButtonElement>("[data-date][tabindex='0']")?.focus();
              }}
            >
              Clear
            </Button>
            <Button size="sm" onClick={apply}>
              Apply
            </Button>
          </div>
        </div>
      </div>
  );

  const Wrap = inline ? "span" : Fragment;
  return (
    <Wrap {...(inline ? { className: styles.inlineWrap } : {})}>
      <span data-slot="date-range-filter" ref={anchorRef} className={cx(styles.root, !isChip && styles.rootField, className)}>
        <button
          ref={triggerRef}
          id={id}
          type="button"
          aria-haspopup="dialog"
          aria-expanded={open}
          aria-controls={open ? dialogId : undefined}
          aria-invalid={invalid || undefined}
          aria-label={ariaLabel ? `${ariaLabel}: ${label}` : undefined}
          aria-labelledby={labelledBy}
          aria-describedby={mergeDescribedBy(field?.describedBy)}
          disabled={disabled}
          onClick={() => {
            if (inline) return;
            if (open) cancel(false);
            else openPopover();
          }}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown" && !open) {
              e.preventDefault();
              openPopover();
            } else if (e.key === "Escape" && open) {
              e.preventDefault();
              e.stopPropagation();
              cancel(true);
            }
          }}
          className={cx(
            isChip ? styles.chip : styles.field,
            hasValue && styles.active,
            hasValue && !disabled && styles.clearable,
            open && styles.open,
          )}
        >
          <IconCalendar size={isChip ? 12 : 16} className={styles.icon} />
          <span id={valueId} className={cx(styles.value, !hasValue && styles.placeholder)}>
            {label}
          </span>
          {hasValue && !disabled ? null : <IconChevronDown size={isChip ? 13 : 16} className={styles.chevron} />}
        </button>

        {hasValue && !disabled ? (
          <button
            type="button"
            className={styles.clear}
            aria-label={`Clear ${ariaLabel ? ariaLabel.toLowerCase() : "date range"}`}
            onClick={clearValue}
          >
            <IconX size={isChip ? 12 : 14} />
          </button>
        ) : null}
      </span>

      {open && today ? (inline ? popup : <Portal>{popup}</Portal>) : null}
    </Wrap>
  );
}

import type { DateRange } from "../DateField/Calendar";
import { addDays, addMonths, compareIso, daysInMonth, formatDate, parseIso, toIso, type IsoDate } from "../DateField/date-utils";

const MONTHS_SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

export type DateRangePreset = {
  id: string;
  label: string;
  /** Resolved against today each time the picker opens, so it never goes stale. */
  range: (today: IsoDate) => { start: IsoDate; end: IsoDate };
};

/** Every default ends today: records are never dated ahead of it. */
export const DEFAULT_DATE_RANGE_PRESETS: ReadonlyArray<DateRangePreset> = [
  { id: "today", label: "Today", range: (t) => ({ start: t, end: t }) },
  { id: "7d", label: "Last 7 days", range: (t) => ({ start: addDays(t, -6), end: t }) },
  { id: "30d", label: "Last 30 days", range: (t) => ({ start: addDays(t, -29), end: t }) },
  {
    id: "month",
    label: "This month",
    range: (t) => {
      const { y, m } = parseIso(t);
      return { start: toIso(y, m, 1), end: t };
    },
  },
  {
    id: "last-month",
    label: "Last month",
    range: (t) => {
      const { y, m } = parseIso(addMonths(t, -1));
      return { start: toIso(y, m, 1), end: toIso(y, m, daysInMonth(y, m)) };
    },
  },
  {
    id: "year",
    label: "This year",
    range: (t) => ({ start: toIso(parseIso(t).y, 1, 1), end: t }),
  },
];

export const EMPTY_RANGE: DateRange = { start: null, end: null };

/** Orders the ends and fills a lone one, so callers only see whole ranges. */
export function normaliseRange({ start, end }: DateRange): DateRange {
  const a = start ?? end;
  const b = end ?? start;
  if (!a || !b) return EMPTY_RANGE;
  return compareIso(a, b) <= 0 ? { start: a, end: b } : { start: b, end: a };
}

export function sameRange(a: DateRange, b: DateRange): boolean {
  return a.start === b.start && a.end === b.end;
}

/** Trims a preset to min/max. null when none of it is inside. */
export function clampRange(range: { start: IsoDate; end: IsoDate }, min?: IsoDate, max?: IsoDate): DateRange | null {
  const start = min && compareIso(range.start, min) < 0 ? min : range.start;
  const end = max && compareIso(range.end, max) > 0 ? max : range.end;
  return compareIso(start, end) <= 0 ? { start, end } : null;
}

/** Inclusive day count. UTC so a daylight-saving change can't shave an hour off a day. */
export function daysInRange(start: IsoDate, end: IsoDate): number {
  const a = parseIso(start);
  const b = parseIso(end);
  return Math.round((Date.UTC(b.y, b.m - 1, b.d) - Date.UTC(a.y, a.m - 1, a.d)) / 86_400_000) + 1;
}

/**
 * Compact trigger label. Shared parts collapse: "1 to 29 Sep 2026",
 * "1 Sep to 29 Oct 2026", "28 Dec 2025 to 3 Jan 2026"; one day is just the day.
 * null when the range is empty.
 */
export function formatDateRange(range: DateRange): string | null {
  const { start, end } = normaliseRange(range);
  if (!start || !end) return null;
  if (start === end) return formatDate(start);
  const a = parseIso(start);
  const b = parseIso(end);
  if (a.y === b.y && a.m === b.m) return `${a.d} to ${b.d} ${MONTHS_SHORT[b.m - 1]} ${b.y}`;
  if (a.y === b.y) return `${a.d} ${MONTHS_SHORT[a.m - 1]} to ${formatDate(end)}`;
  return `${formatDate(start)} to ${formatDate(end)}`;
}
